def first_min_per_key(keys: list[str], scores: list[int]) -> list[int] | None:
    if len(keys)!=len(scores): return None
    order=[];best={}
    for i,key in enumerate(keys):
        if key not in best: order.append(key);best[key]=i
        elif scores[i] < scores[best[key]]: best[key]=i
    return [best[key] for key in order]
